config.command:
set -euo pipefail
BASE={{ project_path }}
cd "$BASE" || { echo 'arch-metrics: Arbeitsverzeichnis nicht erreichbar'; exit 0; }
if [ ! -f scripts/public-readiness/arch-metrics.sh ]; then
  echo '## summary'
  echo 'error=script_missing'
  exit 0
fi
# Kompiliert bei fehlendem target/classes einmalig (~1-2 min), danach ~5 s.
bash scripts/public-readiness/arch-metrics.sh "$BASE" | awk -F'\t' '
  # ## packages ist mit rund 470 Kanten der groesste Abschnitt, die Bewertung nutzt ihn aber nur
  # fuer Schichtkanten; Kopplung steht in ## coupling. Die volle Liste bleibt der Evidenz-Stufe.
  /^## / { inpk = ($0 == "## packages") }
  inpk && $0 == "## packages" { print; print "# gekuerzt auf Schichtkanten (controller->repository, service->controller); Kopplung steht in ## coupling"; next }
  inpk && NF == 3 && $1 !~ /^#/ {
    if (($1 ~ /\.controller/ && $2 ~ /\.repository/) || ($1 ~ /\.service/ && $2 ~ /\.controller/)) { print; layer++ }
    next
  }
  inpk && NF == 0 { if (!layer) print "(keine Schichtkanten)"; print; next }
  inpk { next }
  { print }'

set -euo pipefail
BASE={{ project_path }}
cd "$BASE" || { echo 'frontend-metrics: Arbeitsverzeichnis nicht erreichbar'; exit 0; }
if [ ! -f scripts/public-readiness/frontend-metrics.sh ]; then
  echo '## summary'
  echo 'error=script_missing'
  exit 0
fi
# Reines Lesen, kein npm und kein node_modules — wenige Sekunden.
bash scripts/public-readiness/frontend-metrics.sh "$BASE" | awk '
  # ## packages (Verzeichniskanten) wertet keine Regel aus; Verzeichniskopplung steht in ## coupling.
  /^## / { inpk = ($0 == "## packages") }
  inpk && $0 == "## packages" { print; print "# ausgelassen: Verzeichniskopplung steht in ## coupling"; next }
  inpk && NF == 0 { print; next }
  inpk { next }
  { print }'
